GROUPS = [("Les fondations", ["mlclassique", "donnees", "familles"]), ("Paramétrer et dimensionner", ["compression"]), ("Mettre en production", ["mlops", "adversaire"]),
          ("L’IA dans les secteurs", ["sante", "science", "creatif", "education", "finance", "industrie", "public", "cyber"]), ("L’IA et le travail", ["economie", "geopolitique"]), ("Aller plus loin", ["futurs"])]
def S(key, title, sub, stages, plate, facts, per=3):
    return dict(key=key, title=title, sub=sub, kind="pipeline", per=per, bw=2.3 if per == 3 else 1.9, gap=0.8 if per == 3 else 0.7, y=1.4,
                stages=[dict(n=a, s=b, **({"pal": c} if c else {})) for a, b, c in stages], plate=plate, facts=facts)
def Q(i, q, ch, a, why): return (i, dict(q=q, choices=ch, answer=a, why=f"<p>{why}</p>"))
def CH(dir, no, title, sub, cnt, tag, scenes, pages, qs):
    pg = [dict(kicker=f"Chapitre {no} · {tag}" if i == 0 else f"{no}.{i}", title=t, sub=s, scene=sc, body=b) for i, (t, s, sc, b) in enumerate(pages)]
    pr = {}
    for i, q in qs: pr.setdefault(i, []).append(q)
    return dict(dir=dir, no=no, title=title, sub=sub, cnt=cnt, alt=title, scenes=[S(*x) for x in scenes], pages=pg, practice=pr)
